testcase.failure:
dtype = torch.float32, inverse = False, shape = (1, 16, 4, 64)
@requires_npu @pytest.mark.parametrize("dtype", [torch.float32, torch.bfloat16]) @pytest.mark.parametrize("inverse", [False, True]) @pytest.mark.parametrize("shape", [ (1, 16, 4, 64), # one step, contiguous (2, 32, 8, 128), # the runtime's head width (1, 64, 4, 96), # width the 128-lane tile does not divide: masked tail (1, 8, 2, 6), # a tile much wider than the head (1, 4, 2, 2), # exactly one pair ]) def test_the_fused_kernel_matches_the_reference_bit_for_bit(dtype, inverse, shape): """The claim that matters on hardware: no tolerance, no ulp of slack.""" device = fused_device() x = make_input(shape, scale=1.0, dtype=dtype, device=device) table = make_table(shape[1], shape[-1], scale=1e-5, device=device) expected = cpu_rotate_reference(x, table, inverse) returned = apply_rotary_inplace(x, table, inverse=inverse) assert returned is x mismatches = num_mismatched_bits(x, expected) > assert mismatches == 0, ( f"{mismatches} of {expected.numel()} elements differ from ATen's complex " f"multiply for shape {shape}, dtype {dtype}, inverse={inverse}" ) E AssertionError: 1048 of 4096 elements differ from ATen's complex multiply for shape (1, 16, 4, 64), dtype torch.float32, inverse=False E assert 1048 == 0
tests/test_ascend_rotary.py:532: AssertionError

